CREATE OR REPLACE FUNCTION public.people_guard_employee_write() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN RAISE EXCEPTION 'Use confirmed People changes';END IF;RETURN NEW;END $$;
CREATE TRIGGER people_employee_confirm_only BEFORE INSERT OR UPDATE ON public.hr_employees FOR EACH ROW EXECUTE FUNCTION public.people_guard_employee_write();
CREATE OR REPLACE FUNCTION public.people_guard_history_write() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN RAISE EXCEPTION 'Employment history is written by confirmed changes';END IF;RETURN NEW;END $$;
CREATE TRIGGER people_history_confirm_only BEFORE INSERT OR UPDATE OR DELETE ON public.hr_employee_history FOR EACH ROW EXECUTE FUNCTION public.people_guard_history_write();
CREATE OR REPLACE FUNCTION public.people_feature_write_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid;s jsonb; BEGIN SELECT venue_id INTO v FROM public.hr_employees WHERE id=NEW.employee_id AND tenant_id=NEW.tenant_id;s:=public.people_effective_settings(NEW.tenant_id,v);IF TG_TABLE_NAME='hr_shifts' AND NOT (s->>'rota')::boolean OR TG_TABLE_NAME='hr_attendance' AND s->>'clock_in'='off' OR TG_TABLE_NAME='hr_leave_requests' AND NOT (s->>'leave_requests')::boolean THEN RAISE EXCEPTION 'This People feature is disabled';END IF;RETURN NEW;END $$;
CREATE TRIGGER people_shift_gate BEFORE INSERT OR UPDATE ON public.hr_shifts FOR EACH ROW EXECUTE FUNCTION public.people_feature_write_guard();CREATE TRIGGER people_clock_gate BEFORE INSERT OR UPDATE ON public.hr_attendance FOR EACH ROW EXECUTE FUNCTION public.people_feature_write_guard();CREATE TRIGGER people_leave_gate BEFORE INSERT OR UPDATE ON public.hr_leave_requests FOR EACH ROW EXECUTE FUNCTION public.people_feature_write_guard();
CREATE OR REPLACE FUNCTION public.people_effective_settings(t uuid,v uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NOT NULL AND NOT (public.user_has_tenant(auth.uid(),t) OR public.is_super_admin(auth.uid())) THEN RAISE EXCEPTION 'Tenant access required';END IF;SELECT '{"rota":true,"clock_in":"off","pay_hours":"rota","leave_requests":true,"sick_notes":true,"staff_app":false,"payslips":false,"managers_change_pay":true,"reliability":true,"approvals":"owner_run"}'::jsonb || COALESCE((SELECT values FROM public.people_settings WHERE tenant_id=t AND venue_id IS NULL),'{}'::jsonb) || COALESCE((SELECT values FROM public.people_settings WHERE tenant_id=t AND venue_id=v),'{}'::jsonb) INTO result;IF NOT (result->>'staff_app')::boolean THEN result:=result||'{"payslips":false}'::jsonb;END IF;RETURN result;END $$;
CREATE OR REPLACE FUNCTION public.people_person_access(t uuid,e uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.people_access(t,u) AND EXISTS(SELECT 1 FROM public.hr_employees WHERE id=e AND tenant_id=t AND (venue_id IS NULL OR public.user_has_venue(u,venue_id) OR public.people_owner(t,u) OR public.is_super_admin(u))) $$;
REVOKE ALL ON FUNCTION public.people_person_access(uuid,uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.people_person_access(uuid,uuid,uuid) TO authenticated,service_role;
CREATE POLICY terms_venue_restriction ON public.hr_employment_terms AS RESTRICTIVE FOR SELECT TO authenticated USING(public.people_person_access(tenant_id,employee_id,auth.uid()));
CREATE POLICY docs_venue_restriction ON public.hr_person_documents AS RESTRICTIVE FOR SELECT TO authenticated USING(public.people_person_access(tenant_id,employee_id,auth.uid()));
CREATE POLICY history_people_restriction ON public.hr_employee_history AS RESTRICTIVE FOR SELECT TO authenticated USING(public.people_person_access(tenant_id,employee_id,auth.uid()));